add_filter( 'woocommerce_countries', 'perfectpixel_add_custom_country' );
add_filter( 'woocommerce_continents', 'perfectpixel_add_custom_country_to_continent' );
add_filter( 'woocommerce_states', 'perfectpixel_add_custom_country_states' );

function perfectpixel_add_custom_country( $countries ) {
	$countries['XI'] = __( 'Northern Ireland', 'woocommerce' );
	asort( $countries );
	return $countries;
}

function perfectpixel_add_custom_country_to_continent( $continents ) {
	if ( isset( $continents['EU']['countries'] ) && ! in_array( 'XI', $continents['EU']['countries'], true ) ) {
		$continents['EU']['countries'][] = 'XI';
	}
	return $continents;
}

function perfectpixel_add_custom_country_states( $states ) {
	$states['XI'] = array(
		'ANT' => 'Antrim',
		'ARM' => 'Armagh',
		'DOW' => 'Down',
		'FER' => 'Fermanagh',
		'LDY' => 'Londonderry',
		'TYR' => 'Tyrone',
	);
	return $states;
}
